@Component("jobProfile-handler")
@ProcessingGroup("jobProfile-processing-group")
public class JobProfileEventHandler {
	
	// core constructor
	JobProfileEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateJobProfileEvent
     */
    @EventHandler
    public void handle( CreateJobProfileEvent event) {
        entityManager.persist(new JobProfile(event.getJobProfileId(), event.getTitle(), event.getJobCode(), event.getJobFamily(), event.getCompetencies(), event.getTrainingRecommendations(), event.getPositions(), event.getJobLevel(), event.getExemptStatus()));
    }

    /*
     * @param	event UpdateJobProfileEvent
     */
    @EventHandler
    public JobProfile handle( UpdateJobProfileEvent event) {
    	entityManager.merge(new JobProfile(event.getJobProfileId(), event.getTitle(), event.getJobCode(), event.getJobFamily(), event.getCompetencies(), event.getTrainingRecommendations(), event.getPositions(), event.getJobLevel(), event.getExemptStatus()));
    }
    
    /*
     * @param	event DeleteJobProfileEvent
     */
    @EventHandler
    public void on( DeleteJobProfileEvent event) {
    	JobProfile entity = new JobProfile();
   
    	// ------------------------------------------
    	// apply the JobProfileId
    	// ------------------------------------------
    	entity.setJobProfileId( event.getJobProfileId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final JobProfileRepository jobProfileEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(JobProfileEventHandler.class.getName());

}
